package com.alsafa.native4.core;
import android.database.Cursor;import java.util.*;
/** Read-only customer and sale-invoice search. Supports old invoices by stored name/phone and new invoices by customer_id. */
public final class CustomerInvoiceSearchStore{private final CoreStore.DbProvider provider;public CustomerInvoiceSearchStore(CoreStore.DbProvider p){provider=p;}
 public List<CustomerHit> customers(String query,int limit){String q=trim(query);ArrayList<CustomerHit> out=new ArrayList<>();if(q.isEmpty())return out;String like="%"+q+"%";try(Cursor c=provider.db().rawQuery("SELECT customer_id,name,COALESCE(phone,''),points FROM customers WHERE deleted_at IS NULL AND (name LIKE ? OR phone LIKE ?) ORDER BY updated_at DESC LIMIT ?",new String[]{like,like,String.valueOf(Math.max(1,limit))})){while(c.moveToNext())out.add(new CustomerHit(c.getString(0),c.getString(1),c.getString(2),c.getDouble(3)));}return out;}
 public List<InvoiceHit> invoices(String query,int limit){String q=trim(query),like="%"+q+"%";ArrayList<InvoiceHit> out=new ArrayList<>();if(q.isEmpty())return out;String sql="SELECT i.invoice_id,i.invoice_no,COALESCE(i.customer_id,''),COALESCE(NULLIF(i.customer_name,''),c.name,''),COALESCE(NULLIF(i.customer_phone,''),c.phone,''),i.total,i.currency,i.created_at,COALESCE(ii.description,'') FROM invoices i LEFT JOIN customers c ON c.customer_id=i.customer_id LEFT JOIN invoice_items ii ON ii.invoice_id=i.invoice_id WHERE i.deleted_at IS NULL AND i.invoice_type='SALE' AND (i.invoice_no LIKE ? OR i.customer_name LIKE ? OR i.customer_phone LIKE ? OR c.name LIKE ? OR c.phone LIKE ? OR ii.description LIKE ?) GROUP BY i.invoice_id ORDER BY i.created_at DESC LIMIT ?";try(Cursor c=provider.db().rawQuery(sql,new String[]{like,like,like,like,like,like,String.valueOf(Math.max(1,limit))})){while(c.moveToNext())out.add(new InvoiceHit(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getDouble(5),c.getString(6),c.getLong(7),c.getString(8)));}return out;}
 public List<InvoiceHit> invoicesForCustomer(CustomerHit h,int limit){ArrayList<InvoiceHit> out=new ArrayList<>();String sql="SELECT i.invoice_id,i.invoice_no,COALESCE(i.customer_id,''),COALESCE(NULLIF(i.customer_name,''),?),COALESCE(NULLIF(i.customer_phone,''),?),i.total,i.currency,i.created_at,COALESCE(ii.description,'') FROM invoices i LEFT JOIN invoice_items ii ON ii.invoice_id=i.invoice_id WHERE i.deleted_at IS NULL AND i.invoice_type='SALE' AND (i.customer_id=? OR (i.customer_id IS NULL OR i.customer_id='') AND ((?<>'' AND i.customer_phone=?) OR i.customer_name=?)) GROUP BY i.invoice_id ORDER BY i.created_at DESC LIMIT ?";try(Cursor c=provider.db().rawQuery(sql,new String[]{h.name,h.phone,h.id,h.phone,h.phone,h.name,String.valueOf(Math.max(1,limit))})){while(c.moveToNext())out.add(new InvoiceHit(c.getString(0),c.getString(1),c.getString(2),c.getString(3),c.getString(4),c.getDouble(5),c.getString(6),c.getLong(7),c.getString(8)));}return out;}
 public static final class CustomerHit{public final String id,name,phone;public final double points;CustomerHit(String i,String n,String p,double x){id=i;name=n;phone=p;points=x;}}
 public static final class InvoiceHit{public final String id,no,customerId,customerName,phone,currency,description;public final double total;public final long createdAt;InvoiceHit(String i,String n,String ci,String cn,String p,double t,String c,long at,String d){id=i;no=n;customerId=ci;customerName=cn;phone=p;total=t;currency=c;createdAt=at;description=d;}}
 private static String trim(String s){return s==null?"":s.trim();}}
